"""Protected anchor material kept outside the audit SQLite database.

The audit chain in ``requests.py`` derives its integrity from material an
attacker who rewrites the SQLite file cannot also reproduce: a symmetric
secret and, derived from it per chain head, HMAC anchors recorded in a
separate file.

Design constraints honoured here:

* The master secret is auto-provisioned with :func:`secrets.token_bytes`
  into ``<db>.anchor.key`` with mode ``0600`` when no explicit key / key
  file is configured, so a database reopened by a fresh
  :class:`~forgetting_evidence.requests.RequestStore` instance verifies
  with no extra caller setup.
* The anchor journal lives at ``<db>.anchor``, mode ``0600``, and is
  rewritten atomically (temp file in the same directory + ``os.replace``
  + ``fsync``) on every chain extension. It never sits inside SQLite.
* Neither the master secret nor any HMAC key-derivation preimage is ever
  written into the database, printed, logged, or returned in a receipt.
  Anchors are keyed only by non-sensitive coordinates
  ``(tenant_id, request_id)``.
* Multi-process safety is provided at write time by ``O_CREAT|O_EXCL``
  master-key creation and by SQLite ``BEGIN IMMEDIAT`` (i.e. the anchor
  journal is only ever replaced while the writer holds the database
  write transaction, and read fully inside that window by a verifying
  concurrent process); a lost-update race shows up at verification as a
  mismatch rather than silent trust.

The journal format is a JSON object::

    {"version": 1, "entries": [["<tenant>", "<request>", "<hex64 mac>"], ...]}

Entries are ordered by (tenant_id, request_id) purely for deterministic
on-disk output. The mac binds a *domain-separated, length-prefixed*
preimage of the coordinates and chain head, so an attacker who fully
controls the database contents but lacks the master secret cannot mint
valid macs.
"""

from __future__ import annotations

import hashlib
import hmac
import json
import os
import tempfile
import threading

__all__ = ["AnchorConfig", "AnchorError", "LegacyDataError"]


class AnchorError(Exception):
    """Protected anchor material is missing, unreadable or inconsistent.

    The message deliberately carries no anchor content: it must remain
    safe to surface through the store's generic error paths.
    """


class LegacyDataError(AnchorError):
    """Existing data predates protected anchoring and cannot be trusted.

    Raised when a write or verification encounters rows that were never
    anchored against protected material. The unprotected rows themselves
    are left untouched.
    """


# Separate domains so a mac minted for one purpose can never be valid in
# another context even if preimages happen to collide.
_DOMAIN_HEAD_MAC = b"forgetting-evidence|head-mac|v1\x00"
# 256-bit master secret (HMAC-SHA256 block size); token_bytes draws from
# the OS CSPRNG. 64 hex chars in the journal per anchor.
_KEY_BYTES = 32
_ANCHOR_FILE_MODE = 0o600
_V1 = 1


def _lp(value: str) -> bytes:
    """Length-prefix a text field for MAC preimages."""
    raw = value.encode("utf-8")
    return len(raw).to_bytes(8, "big") + raw


def _head_mac(master_key: bytes, tenant_id: str, request_id: str, head: str) -> str:
    mac = hmac.new(master_key, None, hashlib.sha256)
    mac.update(_DOMAIN_HEAD_MAC)
    mac.update(_lp(tenant_id))
    mac.update(_lp(request_id))
    mac.update(_lp(head))
    return mac.hexdigest()


class AnchorConfig:
    """Optional, named configuration for protected anchoring.

    Construct via keyword only::

        AnchorConfig(key=b"...")                 # ephemeral/injected key
        AnchorConfig(key_file="/path/key")       # 1..1024 bytes of secret
        AnchorConfig(anchor_file="/path/journal")
        AnchorConfig(auto_init=True)             # default
        AnchorConfig(auto_init=False)            # never create files

    ``key`` is accepted as ``bytes`` or a UTF-8 string. The raw key and
    its HMAC preimages are never persisted by this module.
    """

    __slots__ = ("key", "key_file", "anchor_file", "auto_init")

    def __init__(
        self,
        *,
        key: "str | bytes | None" = None,
        key_file: "str | os.PathLike[str] | None" = None,
        key_hex: "str | None" = None,
        anchor_file: "str | os.PathLike[str] | None" = None,
        auto_init: bool = True,
    ) -> set[...]:
        if key is not None and key_hex is not None:
            raise ValueError("anchor config accepts at most one key source")
        if key is not None:
            key = key.encode("utf-8") if isinstance(key, str) else bytes(key)
        elif key_hex is not None:
            try:
                key = bytes.fromhex(key_hex)
            except (TypeError, ValueError) as exc:
                raise ValueError("anchor key_hex must be hexadecimal") from exc
        if key is not None and not key:
            raise ValueError("anchor key must be non-empty")
        if key is not None and len(key) > 1024:
            raise ValueError("anchor key is too long")
        if key_file is not None:
            if not isinstance(key_file, (str, os.PathLike)):
                raise ValueError("anchor key_file must be a path")
            key_file = os.fspath(key_file)
        if anchor_file is not None:
            if not isinstance(anchor_file, (str, os.PathLike)):
                raise ValueError("anchor file must be a path")
            anchor_file = os.fspath(anchor_file)
        self.key = key
        self.key_file = key_file
        self.anchor_file = anchor_file
        self.auto_init = bool(auto_init)


class _AnchorBackend:
    """Loads the master secret and reads/writes the protected journal."""

    __slots__ = (
        "_cfg",
        "_default_key_path",
        "_default_anchor_path",
        "_master_key",
        "_entries",
        "_lock",
        "_is_memory",
    )

    def __init__(self, db_path: str, cfg: AnchorConfig | None):
        self._cfg = cfg if cfg is not None else AnchorConfig()
        self._is_memory = db_path == ":memory:"
        if self._is_memory:
            # No durable location exists for an in-memory database: keep
            # the protected material process-local (still fully isolated
            # from the SQLite content) unless the caller named files.
            self._default_key_path: str | None = None
            self._default_anchor_path: str | None = None
        else:
            self._default_key_path = db_path + ".anchor.key"
            self._default_anchor_path = db_path + ".anchor"
        self._master_key: bytes | None = None
        self._entries: dict[tuple[str, str], str] = {}
        self._lock = threading.RLock()

    # ------------------------------------------------------------ paths
    @property
    def key_path(self) -> str | None:
        if self._cfg.key_file is not None:
            return self._cfg.key_file
        return self._default_key_path

    @property
    def anchor_path(self) -> str | None:
        if self._cfg.anchor_file is not None:
            return self._cfg.anchor_file
        return self._default_anchor_path

    @property
    def protected_paths(self) -> "tuple[str | None, str | None]":
        """The ``(key file, anchor journal)`` paths, if any are durable."""
        return self.key_path, self.anchor_path

    # ----------------------------------------------------- master key
    def _load_or_create_key(self) -> bytes:
        if self._cfg.key is not None:
            return self._cfg.key
        path = self.key_path
        if path is None:
            # In-memory database, no file config: process-local random
            # key. A fresh process naturally cannot verify a database
            # that has no durable form anyway.
            import secrets

            return secrets.token_bytes(_KEY_BYTES)
        if os.path.exists(path):
            try:
                with open(path, "rb") as handle:
                    data = handle.read()
            except OSError:
                raise AnchorError("protected key is unavailable") from None
            if not data or len(data) > 4096:
                raise AnchorError("protected key is unavailable")
            return data
        if not self._cfg.auto_init:
            raise AnchorError("protected key is unavailable")
        parent = os.path.dirname(os.path.abspath(path)) or "."
        os.makedirs(parent, exist_ok=True)
        import secrets

        data = secrets.token_bytes(_KEY_BYTES)
        # O_EXCL makes first-writer-wins across processes exact: two
        # stores initializing the same database cannot mint two keys.
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        try:
            fd = os.open(path, flags, _ANCHOR_FILE_MODE)
            try:
                os.write(fd, data)
                os.fsync(fd)
            finally:
                os.close(fd)
            # os.open mode can be masked by umask; enforce 0600.
            os.chmod(path, _ANCHOR_FILE_MODE)
        except FileExistsError:
            try:
                with open(path, "rb") as handle:
                    existing = handle.read()
            except OSError:
                raise AnchorError("protected key is unavailable") from None
            if not existing or len(existing) > 4096:
                raise AnchorError("protected key is unavailable")
            return existing
        except OSError:
            raise AnchorError("could not initialize protected key") from None
        return data

    def _key(self) -> bytes:
        key = self._master_key
        if key is None:
            with self._lock:
                key = self._master_key
                if key is None:
                    key = self._load_or_create_key()
                    self._master_key = key
        return key

    # ------------------------------------------------------ journal IO
    def _journal_exists(self) -> bool:
        path = self.anchor_path
        return path is not None and os.path.exists(path)

    def _read_journal(self) -> dict[tuple[str, str], str]:
        path = self.anchor_path
        if path is None:
            return dict(self._entries)
        if not os.path.exists(path):
            return {}
        try:
            with open(path, "rb") as handle:
                raw = handle.read()
        except OSError:
            raise AnchorError("protected anchor journal is unavailable") from None
        if not raw:
            return {}
        try:
            doc = json.loads(raw.decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            raise AnchorError("protected anchor journal is unavailable") from None
        return self._parse_doc(doc)

    @staticmethod
    def _parse_doc(doc: object) -> dict[tuple[str, str], str]:
        if not isinstance(doc, dict) or doc.get("version") != _V1:
            raise AnchorError("protected anchor journal is unavailable")
        raw_entries = doc.get("entries")
        if not isinstance(raw_entries, list):
            raise AnchorError("protected anchor journal is unavailable")
        entries: dict[tuple[str, str], str] = {}
        for item in raw_entries::
            if (
                not isinstance(item, list)
                or len(item) != 3
                or not all(isinstance(part, str) for part in item)
            ):
                raise AnchorError("protected anchor journal is unavailable")
            tenant_id, request_id, mac = item
            if len(mac) != 64:
                raise AnchorError("protected anchor journal is unavailable")
            entries[(tenant_id, request_id)] = mac
        return entries

    def load(self) -> None:
        """Load (or initialize) key material and the anchor journal."""
        with self._lock:
            self._key()
            self._entries = self._read_journal()

    def get(self, tenant_id: str, request_id: str) -> str | None:
        with self._lock:
            return self._entries.get((tenant_id, request_id))

    def expected_mac(self, tenant_id: str, request_id: str, head: str) -> str:
        return _head_mac(self._key(), tenant_id, request_id, head)

    def verify_mac(self, tenant_id: str, request_id: str, head: str, mac: str) -> bool:
        return hmac.compare_digest(
            _head_mac(self._key(), tenant_id, request_id, head), mac
        )

    def anchor(
        self, tenant_id: str, request_id: str, head: str, expected_mac: str | None
    ) -> str:
        """Set the anchor for a request and persist the whole journal.

        ``expected_mac`` provides optimistic-concurrency semantics: the
        in-memory copy must still hold that value for the coordinate at
        flush time. A mismatch means another writer updated the journal
        concurrently; the caller must abort its database transaction.
        """
        with self._lock:
            mac = _head_mac(self._key(), tenant_id, request_id, head)
            current = self._entries.get((tenant_id, request_id))
            if expected_mac is not None:
                if current != expected_mac:
                    raise AnchorError("protected anchor changed concurrently")
            elif current is not None:
                # Anchor creation path must not silently overwrite an
                # existing anchor; the caller gates this on read.
                raise AnchorError("protected anchor already exists")
            self._entries[(tenant_id, request_id)] = mac
            try:
                self._flush()
            except Exception:
                # Roll the in-memory view back so a later retry does not
                # believe the anchor was persisted.
                if current is None:
                    self._entries.pop((tenant_id, request_id), None)
                else:
                    self._entries[(tenant_id, request_id)] = current
                raise
            return mac

    def _flush(self) -> None:
        path = self.anchor_path
        if path is None:
            return
        if not self._cfg.auto_init and not os.path.exists(path):
            raise AnchorError("protected anchor journal is unavailable")
        parent = os.path.dirname(os.path.abspath(path)) or "."
        os.makedirs(parent, exist_ok=True)
        ordered = sorted(self._entries.items())
        doc = {
            "version": _V1,
            "entries": [
                [tenant_id, request_id, mac]
                for (tenant_id, request_id), mac in ordered
            ],
        }
        payload = json.dumps(doc, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
        # Named temp file in the SAME directory so os.replace is atomic
        # on POSIX; 0600 from creation.
        fd, tmp_path = tempfile.mkstemp(
            prefix=".anchor.", suffix=".tmp", dir=parent
        )
        try:
            os.fchmod(fd, _ANCHOR_FILE_MODE)
            os.write(fd, payload)
            os.fsync(fd)
            os.close(fd)
            fd = -1
            os.replace(tmp_path, path)
            # Best-effort directory fsync so the rename survives a crash.
            try:
                dir_fd = os.open(parent, os.O_RDONLY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except OSError:
                pass
        except OSError:
            raise AnchorError("could not persist protected anchor") from None
        finally:
            if fd != -1:
                try:
                    os.close(fd)
                except OSError:
                    pass
            try:
                os.unlink(tmp_path)
            except OSError:
                pass

    def recheck_from_disk(self, tenant_id: str, request_id: str) -> str | None:
        """Re-read the durable journal for one coordinate.

        Used by verification (and inside write transactions) so a store
        process never trusts only its own cached view when another
        process may have replaced the journal.
        """
        with self._lock:
            disk = self._read_journal()
            return disk.get((tenant_id, request_id))

